fixed = 0
for fpath_rel, new_body in answers.items():
    fpath = os.path.join(OUT, fpath_rel)
    if not os.path.exists(fpath):
        print(f"  MISSING: {fpath_rel}")
        continue

    lines = open(fpath, encoding='utf-8').read().split('\n')

    # Find 答题示范 heading
    ans_line = None
    for i, line in enumerate(lines):
        if line.startswith('###') and '答题示范' in line:
            ans_line = i
            break

    if ans_line is None:
        print(f"  NO SECTION: {fpath_rel}")
        continue

    # Find next ### section
    next_section = len(lines)
    for i in range(ans_line + 1, len(lines)):
        if lines[i].startswith('###'):
            next_section = i
            break

    # Replace
    new_lines = lines[:ans_line+1] + ['', new_body, ''] + lines[next_section:]
    with open(fpath, 'w', encoding='utf-8') as f:
        f.write('\n'.join(new_lines))

    print(f"  DONE: {os.path.basename(fpath_rel)[:40]}")
    fixed += 1

print(f"\nFixed {fixed}/5 samples.")
